contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeSelf = address(this).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            (reverted && address(c).balance == beforeBalance && address(this).balance == beforeSelf && c.depositsCount() == beforeCount)
            ||
            (!reverted && beforeBalance >= amount && address(c).balance == beforeBalance - amount && address(this).balance == beforeSelf + amount && c.depositsCount() == beforeCount)
        );
    }
}

