// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeBalance = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeSelf = address(this).balance;
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        assertTrue((reverted && address(c).balance == beforeBalance && address(this).balance == beforeSelf && c.depositsCount() == beforeCount)
            ||
            (!reverted && beforeBalance >= amount && address(c).balance == beforeBalance - amount && address(this).balance == beforeSelf + amount && c.depositsCount() == beforeCount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
